  'system', 'user', 'assistant', 'tool'
);
CREATE TYPE core.relationship_kind AS ENUM (
  'is_a', 'part_of', 'contains', 'depends_on', 'prerequisite_of',
  'related_to', 'contraindicates', 'causes', 'affects'
);

CREATE OR REPLACE FUNCTION core.set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at := statement_timestamp();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION core.current_user_id()
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  SELECT auth.uid();
$$;

CREATE OR REPLACE FUNCTION core.jwt_claim_text(claim_name text)
RETURNS text
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  SELECT auth.jwt() ->> claim_name;
$$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA core FROM PUBLIC;
GRANT USAGE ON SCHEMA core TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION core.current_user_id() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION core.jwt_claim_text(text) TO authenticated, service_role;

-- Identity and access management.
-- auth.users remains the authentication source of truth.

CREATE TABLE iam.user_accounts (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  status core.account_status NOT NULL DEFAULT 'active',
  locale text NOT NULL DEFAULT 'fr-FR',
  timezone text NOT NULL DEFAULT 'Europe/Paris',
  onboarding_completed_at timestamptz,
  last_seen_at timestamptz,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT user_accounts_locale_ck CHECK (locale ~ '^[a-z]{2}(-[A-Z]{2})?$'),
  CONSTRAINT user_accounts_deleted_ck CHECK (
    (status = 'deleted' AND deleted_at IS NOT NULL) OR status <> 'deleted'
  )
);
COMMENT ON TABLE iam.user_accounts IS
  'Application account projection for each auth.users identity; never stores credentials or JWTs.';

CREATE TABLE iam.profiles (
  user_id uuid PRIMARY KEY REFERENCES iam.user_accounts(user_id) ON DELETE CASCADE,
  display_name text,
  given_name text,
  family_name text,
  biography text,
  avatar_asset_id uuid,
  profile_visibility text NOT NULL DEFAULT 'private',
  organization_name text,
  profession_title text,
  training_program text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT profiles_visibility_ck
    CHECK (profile_visibility IN ('private', 'friends', 'public')),
  CONSTRAINT profiles_display_name_ck
    CHECK (display_name IS NULL OR char_length(display_name) BETWEEN 1 AND 80)
);
COMMENT ON TABLE iam.profiles IS
  'Non-sensitive user-facing profile data separated from authentication and preferences.';

CREATE TABLE iam.user_preferences (
  user_id uuid PRIMARY KEY REFERENCES iam.user_accounts(user_id) ON DELETE CASCADE,
  theme text NOT NULL DEFAULT 'system',
  reduced_motion boolean NOT NULL DEFAULT false,
  haptics_enabled boolean NOT NULL DEFAULT true,
  sounds_enabled boolean NOT NULL DEFAULT true,
  content_locale text NOT NULL DEFAULT 'fr-FR',
  daily_goal_xp integer NOT NULL DEFAULT 30,
  study_reminder_time time,
  accessibility jsonb NOT NULL DEFAULT '{}'::jsonb,
  learning_preferences jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT user_preferences_theme_ck CHECK (theme IN ('system', 'light', 'dark')),
  CONSTRAINT user_preferences_daily_goal_ck CHECK (daily_goal_xp BETWEEN 0 AND 10000),
  CONSTRAINT user_preferences_accessibility_object_ck
    CHECK (jsonb_typeof(accessibility) = 'object'),
  CONSTRAINT user_preferences_learning_object_ck
    CHECK (jsonb_typeof(learning_preferences) = 'object')
);
COMMENT ON TABLE iam.user_preferences IS
  'One normalized preference record per user; JSONB is limited to extensible UI and learning options.';

CREATE TABLE iam.user_devices (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES iam.user_accounts(user_id) ON DELETE CASCADE,
  installation_id uuid NOT NULL,
  platform core.platform NOT NULL,
  device_model text,
  os_version text,
  app_version text,
  locale text,
  timezone text,
  push_capable boolean NOT NULL DEFAULT false,
  trusted_at timestamptz,
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, installation_id)
);
COMMENT ON TABLE iam.user_devices IS
  'Registered app installations for trust, push routing, offline synchronization and revocation.';
CREATE INDEX user_devices_user_seen_idx
  ON iam.user_devices (user_id, last_seen_at DESC);
CREATE INDEX user_devices_active_idx
  ON iam.user_devices (user_id, platform) WHERE revoked_at IS NULL;

CREATE TABLE iam.user_sessions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES iam.user_accounts(user_id) ON DELETE CASCADE,
  device_id uuid REFERENCES iam.user_devices(id) ON DELETE SET NULL,
  auth_session_id uuid,
  ip_hash text,
  user_agent text,
  started_at timestamptz NOT NULL DEFAULT now(),
  last_activity_at timestamptz NOT NULL DEFAULT now(),
  ended_at timestamptz,
  end_reason text,
  CONSTRAINT user_sessions_end_ck CHECK (
    ended_at IS NULL OR ended_at >= started_at
  )
);
COMMENT ON TABLE iam.user_sessions IS
  'Auditable session metadata mirror; access and refresh tokens remain exclusively in Supabase Auth.';
CREATE INDEX user_sessions_active_idx
  ON iam.user_sessions (user_id, last_activity_at DESC) WHERE ended_at IS NULL;
CREATE UNIQUE INDEX user_sessions_auth_session_uidx
  ON iam.user_sessions (auth_session_id) WHERE auth_session_id IS NOT NULL;

CREATE TABLE iam.external_identities (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES iam.user_accounts(user_id) ON DELETE CASCADE,
  auth_identity_id uuid NOT NULL,
  provider text NOT NULL,
  provider_subject_hash text NOT NULL,
  linked_at timestamptz NOT NULL DEFAULT now(),
  last_login_at timestamptz,
  unlinked_at timestamptz,
  UNIQUE (auth_identity_id),
  UNIQUE (provider, provider_subject_hash)
);
COMMENT ON TABLE iam.external_identities IS
  'Minimal non-secret audit projection of OAuth, passwordless and magic-link identities managed by Supabase Auth.';
CREATE INDEX external_identities_user_idx
  ON iam.external_identities (user_id, linked_at DESC);

CREATE TABLE iam.mfa_preferences (
  user_id uuid PRIMARY KEY REFERENCES iam.user_accounts(user_id) ON DELETE CASCADE,
  required boolean NOT NULL DEFAULT false,
  preferred_factor text,
  enrolled_factor_count integer NOT NULL DEFAULT 0,
  last_verified_at timestamptz,
  recovery_codes_rotated_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT mfa_factor_ck
    CHECK (preferred_factor IS NULL OR preferred_factor IN ('totp', 'phone', 'webauthn')),
  CONSTRAINT mfa_count_ck CHECK (enrolled_factor_count >= 0)
);
COMMENT ON TABLE iam.mfa_preferences IS
  'Application MFA policy projection; secrets and factor material stay in Supabase Auth.';

CREATE TABLE iam.security_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  device_id uuid REFERENCES iam.user_devices(id) ON DELETE SET NULL,
  event_type text NOT NULL,
  severity text NOT NULL DEFAULT 'info',
  ip_hash text,
  user_agent text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT security_events_severity_ck
    CHECK (severity IN ('info', 'warning', 'critical')),
  CONSTRAINT security_events_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE iam.security_events IS
  'Append-only security history for login, logout, MFA, lockout, credential and suspicious-access events.';
CREATE INDEX security_events_user_time_idx
  ON iam.security_events (user_id, occurred_at DESC);
CREATE INDEX security_events_type_time_idx
  ON iam.security_events (event_type, occurred_at DESC);
CREATE INDEX security_events_metadata_gin
  ON iam.security_events USING gin (metadata jsonb_path_ops);

CREATE TABLE iam.organizations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  name text NOT NULL,
  organization_type text NOT NULL,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  settings jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT organizations_type_ck CHECK (
    organization_type IN ('training_institute', 'employer', 'healthcare_facility', 'partner', 'internal')
  ),
  CONSTRAINT organizations_settings_ck CHECK (jsonb_typeof(settings) = 'object')
);
COMMENT ON TABLE iam.organizations IS
  'Training institutes, employers and partner organizations used for scoped access and cohorts.';

CREATE TABLE iam.organization_memberships (
  organization_id uuid NOT NULL REFERENCES iam.organizations(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES iam.user_accounts(user_id) ON DELETE CASCADE,
  membership_status text NOT NULL DEFAULT 'active',
  external_reference text,
  joined_at timestamptz NOT NULL DEFAULT now(),
  left_at timestamptz,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  PRIMARY KEY (organization_id, user_id),
  CONSTRAINT organization_membership_status_ck CHECK (
    membership_status IN ('invited', 'active', 'suspended', 'left')
  ),
  CONSTRAINT organization_memberships_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE iam.organization_memberships IS
  'Membership relation between users and institutes/employers without duplicating user profiles.';
CREATE INDEX organization_memberships_user_idx
  ON iam.organization_memberships (user_id, membership_status);

CREATE TABLE iam.roles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  name text NOT NULL,
  description text,
  system_role boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE iam.roles IS
  'Named RBAC roles such as learner, trainer, medical_reviewer, content_editor and administrator.';

CREATE TABLE iam.permissions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  domain text NOT NULL,
  action text NOT NULL,
  description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (domain, action)
);
COMMENT ON TABLE iam.permissions IS
  'Atomic RBAC permissions, kept independent from roles to avoid authorization duplication.';

CREATE TABLE iam.role_permissions (
  role_id uuid NOT NULL REFERENCES iam.roles(id) ON DELETE CASCADE,
  permission_id uuid NOT NULL REFERENCES iam.permissions(id) ON DELETE CASCADE,
  granted_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (role_id, permission_id)
);
COMMENT ON TABLE iam.role_permissions IS
  'Many-to-many mapping from RBAC roles to atomic permissions.';
CREATE INDEX role_permissions_permission_idx
  ON iam.role_permissions (permission_id, role_id);

CREATE TABLE iam.user_roles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES iam.user_accounts(user_id) ON DELETE CASCADE,
  role_id uuid NOT NULL REFERENCES iam.roles(id) ON DELETE CASCADE,
  organization_id uuid REFERENCES iam.organizations(id) ON DELETE CASCADE,
  formation_id uuid,
  granted_by uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  granted_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz,
  revoked_at timestamptz,
  CONSTRAINT user_roles_scope_ck CHECK (num_nonnulls(organization_id, formation_id) <= 1),
  CONSTRAINT user_roles_expiry_ck CHECK (
    expires_at IS NULL OR expires_at > granted_at
  )
);
COMMENT ON TABLE iam.user_roles IS
  'Scoped, expirable user-role grants with complete provenance.';
CREATE UNIQUE INDEX user_roles_active_uidx
  ON iam.user_roles (
    user_id,
    role_id,
    COALESCE(organization_id, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(formation_id, '00000000-0000-0000-0000-000000000000'::uuid)
  )
  WHERE revoked_at IS NULL;
CREATE INDEX user_roles_authorization_idx
  ON iam.user_roles (user_id, organization_id, formation_id)
  WHERE revoked_at IS NULL;

CREATE TABLE iam.user_consents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES iam.user_accounts(user_id) ON DELETE CASCADE,
  consent_code text NOT NULL,
  document_version text NOT NULL,
  granted boolean NOT NULL,
  locale text NOT NULL DEFAULT 'fr-FR',
  source text NOT NULL DEFAULT 'app',
  evidence jsonb NOT NULL DEFAULT '{}'::jsonb,
  recorded_at timestamptz NOT NULL DEFAULT now(),
  withdrawn_at timestamptz,
  CONSTRAINT user_consents_evidence_ck CHECK (jsonb_typeof(evidence) = 'object'),
  CONSTRAINT user_consents_withdrawn_ck CHECK (
    withdrawn_at IS NULL OR withdrawn_at >= recorded_at
  )
);
COMMENT ON TABLE iam.user_consents IS
  'Immutable consent history for terms, privacy, analytics, AI memory and communication channels.';
CREATE INDEX user_consents_latest_idx
  ON iam.user_consents (user_id, consent_code, recorded_at DESC);

CREATE TABLE iam.account_recovery_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  recovery_type text NOT NULL,
  status text NOT NULL,
  requested_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT recovery_status_ck
    CHECK (status IN ('requested', 'verified', 'completed', 'expired', 'cancelled')),
  CONSTRAINT recovery_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE iam.account_recovery_events IS
  'Audit-only history of account recovery and security-sensitive identity changes.';
CREATE INDEX account_recovery_user_idx
  ON iam.account_recovery_events (user_id, requested_at DESC);

CREATE TRIGGER user_accounts_set_updated_at
BEFORE UPDATE ON iam.user_accounts
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();
CREATE TRIGGER profiles_set_updated_at
BEFORE UPDATE ON iam.profiles
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();
CREATE TRIGGER user_preferences_set_updated_at
BEFORE UPDATE ON iam.user_preferences
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();
CREATE TRIGGER user_devices_set_updated_at
BEFORE UPDATE ON iam.user_devices
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();
CREATE TRIGGER mfa_preferences_set_updated_at
BEFORE UPDATE ON iam.mfa_preferences
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();
CREATE TRIGGER roles_set_updated_at
BEFORE UPDATE ON iam.roles
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();
CREATE TRIGGER organizations_set_updated_at
BEFORE UPDATE ON iam.organizations
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();

-- Media catalog, regulatory sources, Master Knowledge Base and curriculum.

CREATE TABLE media.assets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stable_key text NOT NULL UNIQUE,
  kind core.asset_kind NOT NULL,
  storage_bucket text NOT NULL,
  storage_path text NOT NULL,
  mime_type text NOT NULL,
  byte_size bigint NOT NULL,
  checksum_sha256 text NOT NULL,
  width_px integer,
  height_px integer,
  duration_ms integer,
  accessibility_label text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  created_by uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  UNIQUE (storage_bucket, storage_path),
  UNIQUE (checksum_sha256, byte_size),
  CONSTRAINT assets_byte_size_ck CHECK (byte_size > 0),
  CONSTRAINT assets_dimensions_ck CHECK (
    (width_px IS NULL OR width_px > 0)
    AND (height_px IS NULL OR height_px > 0)
    AND (duration_ms IS NULL OR duration_ms >= 0)
  ),
  CONSTRAINT assets_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE media.assets IS
  'Canonical media metadata; binary objects remain in private or public Supabase Storage buckets.';
CREATE INDEX assets_kind_status_idx ON media.assets (kind, status, created_at DESC);
CREATE INDEX assets_metadata_gin ON media.assets USING gin (metadata jsonb_path_ops);
CREATE INDEX assets_search_trgm_idx ON media.assets USING gin (stable_key gin_trgm_ops);

CREATE TABLE media.asset_variants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_asset_id uuid NOT NULL REFERENCES media.assets(id) ON DELETE CASCADE,
  variant_key text NOT NULL,
  storage_bucket text NOT NULL,
  storage_path text NOT NULL,
  mime_type text NOT NULL,
  byte_size bigint NOT NULL,
  width_px integer,
  height_px integer,
  bitrate_kbps integer,
  transformation jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (source_asset_id, variant_key),
  UNIQUE (storage_bucket, storage_path),
  CONSTRAINT asset_variants_size_ck CHECK (byte_size > 0),
  CONSTRAINT asset_variants_transform_ck CHECK (jsonb_typeof(transformation) = 'object')
);
COMMENT ON TABLE media.asset_variants IS
  'Optimized derivatives such as thumbnails, WebP/AVIF, mobile video, waveform and low-poly 3D.';
CREATE INDEX asset_variants_source_idx
  ON media.asset_variants (source_asset_id, variant_key);

CREATE TABLE media.asset_localizations (
  asset_id uuid NOT NULL REFERENCES media.assets(id) ON DELETE CASCADE,
  locale text NOT NULL,
  title text,
  caption text,
  alt_text text NOT NULL,
  transcript text,
  PRIMARY KEY (asset_id, locale)
);
COMMENT ON TABLE media.asset_localizations IS
  'Localized accessible titles, captions, alternative text and media transcripts.';

CREATE TABLE media.asset_licenses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_id uuid NOT NULL REFERENCES media.assets(id) ON DELETE CASCADE,
  license_name text NOT NULL,
  rights_holder text,
  source_url text,
  valid_from timestamptz,
  valid_until timestamptz,
  usage_terms text,
  evidence_asset_id uuid REFERENCES media.assets(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT asset_license_dates_ck CHECK (
    valid_until IS NULL OR valid_from IS NULL OR valid_until > valid_from
  )
);
COMMENT ON TABLE media.asset_licenses IS
  'Rights and provenance for every externally sourced or commissioned media asset.';
CREATE INDEX asset_licenses_asset_idx ON media.asset_licenses (asset_id);

ALTER TABLE iam.profiles
  ADD CONSTRAINT profiles_avatar_asset_fk
  FOREIGN KEY (avatar_asset_id) REFERENCES media.assets(id) ON DELETE SET NULL;

CREATE TABLE knowledge.source_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stable_key text NOT NULL UNIQUE,
  title text NOT NULL,
  publisher text,
  authority core.source_authority NOT NULL,
  document_type text NOT NULL,
  canonical_url text,
  jurisdiction text NOT NULL DEFAULT 'FR',
  language text NOT NULL DEFAULT 'fr',
  current_version_id uuid,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT source_documents_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE knowledge.source_documents IS
  'Stable identity for DEA, HAS, Code de la santé publique and other auditable medical sources.';
CREATE INDEX source_documents_authority_status_idx
  ON knowledge.source_documents (authority, status);
CREATE INDEX source_documents_title_trgm_idx
  ON knowledge.source_documents USING gin (title gin_trgm_ops);

CREATE TABLE knowledge.source_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_document_id uuid NOT NULL REFERENCES knowledge.source_documents(id) ON DELETE CASCADE,
  version_label text NOT NULL,
  published_on date,
  effective_from date,
  effective_until date,
  checksum_sha256 text,
  media_asset_id uuid REFERENCES media.assets(id) ON DELETE SET NULL,
  page_count integer,
  imported_at timestamptz NOT NULL DEFAULT now(),
  supersedes_version_id uuid REFERENCES knowledge.source_versions(id) ON DELETE SET NULL,
  review_status core.review_status NOT NULL DEFAULT 'pending_review',
  UNIQUE (source_document_id, version_label),
  CONSTRAINT source_versions_dates_ck CHECK (
    effective_until IS NULL OR effective_from IS NULL OR effective_until >= effective_from
  ),
  CONSTRAINT source_versions_pages_ck CHECK (page_count IS NULL OR page_count > 0)
);
COMMENT ON TABLE knowledge.source_versions IS
  'Immutable editions of a source document so every learning claim remains reproducible.';
CREATE INDEX source_versions_document_idx
  ON knowledge.source_versions (source_document_id, effective_from DESC NULLS LAST);

ALTER TABLE knowledge.source_documents
  ADD CONSTRAINT source_documents_current_version_fk
  FOREIGN KEY (current_version_id) REFERENCES knowledge.source_versions(id)
  ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE knowledge.source_sections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_version_id uuid NOT NULL REFERENCES knowledge.source_versions(id) ON DELETE CASCADE,
  parent_section_id uuid REFERENCES knowledge.source_sections(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  heading text,
  page_from integer,
  page_to integer,
  article_reference text,
  extracted_text text,
  search_vector tsvector GENERATED ALWAYS AS (
    to_tsvector('french', coalesce(heading, '') || ' ' || coalesce(extracted_text, ''))
  ) STORED,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE (source_version_id, stable_key),
  CONSTRAINT source_sections_pages_ck CHECK (
    (page_from IS NULL AND page_to IS NULL)
    OR (page_from > 0 AND page_to >= page_from)
  ),
  CONSTRAINT source_sections_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE knowledge.source_sections IS
  'Page- or article-level citation units used by questions, concepts and Pulse AI.';
CREATE INDEX source_sections_parent_idx ON knowledge.source_sections (parent_section_id);
CREATE INDEX source_sections_search_idx ON knowledge.source_sections USING gin (search_vector);
CREATE INDEX source_sections_article_idx
  ON knowledge.source_sections (article_reference) WHERE article_reference IS NOT NULL;

CREATE TABLE knowledge.regulatory_updates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_document_id uuid NOT NULL REFERENCES knowledge.source_documents(id) ON DELETE CASCADE,
  source_version_id uuid REFERENCES knowledge.source_versions(id) ON DELETE SET NULL,
  update_type text NOT NULL,
  title text NOT NULL,
  summary text NOT NULL,
  detected_at timestamptz NOT NULL,
  effective_at timestamptz,
  reviewed_at timestamptz,
  reviewed_by uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  impact_assessment jsonb NOT NULL DEFAULT '{}'::jsonb,
  status core.review_status NOT NULL DEFAULT 'pending_review',
  CONSTRAINT regulatory_updates_impact_ck CHECK (jsonb_typeof(impact_assessment) = 'object')
);
COMMENT ON TABLE knowledge.regulatory_updates IS
  'Tracked changes to official medical and regulatory sources with explicit impact review.';
CREATE INDEX regulatory_updates_status_idx
  ON knowledge.regulatory_updates (status, detected_at DESC);

CREATE TABLE knowledge.medical_domains (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  parent_domain_id uuid REFERENCES knowledge.medical_domains(id) ON DELETE RESTRICT,
  code text NOT NULL UNIQUE,
  name text NOT NULL,
  description text,
  sort_order integer NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE knowledge.medical_domains IS
  'Hierarchical medical taxonomy shared by all formations and learning modes.';
CREATE INDEX medical_domains_parent_idx
  ON knowledge.medical_domains (parent_domain_id, sort_order);

CREATE TABLE knowledge.competencies (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stable_key text NOT NULL UNIQUE,
  domain_id uuid NOT NULL REFERENCES knowledge.medical_domains(id) ON DELETE RESTRICT,
  name text NOT NULL,
  description text NOT NULL,
  difficulty core.difficulty_level NOT NULL DEFAULT 'easy',
  mastery_threshold numeric(5,2) NOT NULL DEFAULT 80,
  min_successful_attempts integer NOT NULL DEFAULT 2,
  review_status core.review_status NOT NULL DEFAULT 'pending_review',
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT competencies_mastery_ck CHECK (mastery_threshold BETWEEN 0 AND 100),
  CONSTRAINT competencies_attempts_ck CHECK (min_successful_attempts > 0),
  CONSTRAINT competencies_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE knowledge.competencies IS
  'Stable, reusable Master Knowledge Base competencies with explicit mastery criteria.';
CREATE INDEX competencies_domain_status_idx
  ON knowledge.competencies (domain_id, status);
CREATE INDEX competencies_key_trgm_idx
  ON knowledge.competencies USING gin (stable_key gin_trgm_ops);
CREATE INDEX competencies_metadata_gin
  ON knowledge.competencies USING gin (metadata jsonb_path_ops);

CREATE TABLE knowledge.competency_prerequisites (
  competency_id uuid NOT NULL REFERENCES knowledge.competencies(id) ON DELETE CASCADE,
  prerequisite_competency_id uuid NOT NULL REFERENCES knowledge.competencies(id) ON DELETE RESTRICT,
  minimum_mastery numeric(5,2) NOT NULL DEFAULT 70,
  required boolean NOT NULL DEFAULT true,
  PRIMARY KEY (competency_id, prerequisite_competency_id),
  CONSTRAINT competency_prerequisites_not_self_ck
    CHECK (competency_id <> prerequisite_competency_id),
  CONSTRAINT competency_prerequisites_mastery_ck
    CHECK (minimum_mastery BETWEEN 0 AND 100)
);
COMMENT ON TABLE knowledge.competency_prerequisites IS
  'Directed prerequisite graph between competencies; cycles are rejected by validation tooling.';
CREATE INDEX competency_prerequisites_reverse_idx
  ON knowledge.competency_prerequisites (prerequisite_competency_id, competency_id);

CREATE TABLE knowledge.medical_concepts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stable_key text NOT NULL UNIQUE,
  domain_id uuid NOT NULL REFERENCES knowledge.medical_domains(id) ON DELETE RESTRICT,
  preferred_label text NOT NULL,
  definition text NOT NULL,
  synonyms text[] NOT NULL DEFAULT ARRAY[]::text[],
  language text NOT NULL DEFAULT 'fr',
  review_status core.review_status NOT NULL DEFAULT 'pending_review',
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  search_vector tsvector GENERATED ALWAYS AS (
    to_tsvector('french', preferred_label || ' ' || definition || ' ' || array_to_string(synonyms, ' '))
  ) STORED,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT medical_concepts_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE knowledge.medical_concepts IS
  'Normalized medical concepts used by content, semantic search and the medical graph.';
CREATE INDEX medical_concepts_domain_idx
  ON knowledge.medical_concepts (domain_id, status);
CREATE INDEX medical_concepts_search_idx
  ON knowledge.medical_concepts USING gin (search_vector);
CREATE INDEX medical_concepts_synonyms_idx
  ON knowledge.medical_concepts USING gin (synonyms);

CREATE TABLE knowledge.concept_relationships (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_concept_id uuid NOT NULL REFERENCES knowledge.medical_concepts(id) ON DELETE CASCADE,
  target_concept_id uuid NOT NULL REFERENCES knowledge.medical_concepts(id) ON DELETE CASCADE,
  relationship core.relationship_kind NOT NULL,
  confidence numeric(5,4) NOT NULL DEFAULT 1,
  source_section_id uuid REFERENCES knowledge.source_sections(id) ON DELETE SET NULL,
  review_status core.review_status NOT NULL DEFAULT 'pending_review',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (source_concept_id, target_concept_id, relationship),
  CONSTRAINT concept_relationships_not_self_ck CHECK (source_concept_id <> target_concept_id),
  CONSTRAINT concept_relationships_confidence_ck CHECK (confidence BETWEEN 0 AND 1),
  CONSTRAINT concept_relationships_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE knowledge.concept_relationships IS
  'Directed, sourced edges of the MedLingo medical knowledge graph.';
CREATE INDEX concept_relationships_target_idx
  ON knowledge.concept_relationships (target_concept_id, relationship);

CREATE TABLE knowledge.concept_competencies (
  concept_id uuid NOT NULL REFERENCES knowledge.medical_concepts(id) ON DELETE CASCADE,
  competency_id uuid NOT NULL REFERENCES knowledge.competencies(id) ON DELETE CASCADE,
  relevance numeric(5,4) NOT NULL DEFAULT 1,
  PRIMARY KEY (concept_id, competency_id),
  CONSTRAINT concept_competencies_relevance_ck CHECK (relevance BETWEEN 0 AND 1)
);
COMMENT ON TABLE knowledge.concept_competencies IS
  'Many-to-many mapping that connects the medical graph to measurable competencies.';
CREATE INDEX concept_competencies_competency_idx
  ON knowledge.concept_competencies (competency_id, concept_id);

CREATE TABLE knowledge.concept_sources (
  concept_id uuid NOT NULL REFERENCES knowledge.medical_concepts(id) ON DELETE CASCADE,
  source_section_id uuid NOT NULL REFERENCES knowledge.source_sections(id) ON DELETE RESTRICT,
  evidence_kind text NOT NULL DEFAULT 'supports',
  quotation_hash text,
  PRIMARY KEY (concept_id, source_section_id),
  CONSTRAINT concept_sources_kind_ck
    CHECK (evidence_kind IN ('defines', 'supports', 'updates', 'contradicts'))
);
COMMENT ON TABLE knowledge.concept_sources IS
  'Auditable evidence links from concepts to precise document sections.';

CREATE TABLE knowledge.concept_embeddings (
  concept_id uuid NOT NULL REFERENCES knowledge.medical_concepts(id) ON DELETE CASCADE,
  embedding_model text NOT NULL,
  dimensions integer NOT NULL,
  embedding extensions.vector(1536) NOT NULL,
  content_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (concept_id, embedding_model),
  CONSTRAINT concept_embeddings_dimensions_ck CHECK (dimensions = 1536)
);
COMMENT ON TABLE knowledge.concept_embeddings IS
  'Versioned semantic vectors for concept retrieval; one embedding per model and concept.';
CREATE INDEX concept_embeddings_hnsw_idx
  ON knowledge.concept_embeddings USING hnsw (embedding vector_cosine_ops);

CREATE TABLE knowledge.tags (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  label text NOT NULL,
  description text,
  parent_tag_id uuid REFERENCES knowledge.tags(id) ON DELETE SET NULL,
  active boolean NOT NULL DEFAULT true
);
COMMENT ON TABLE knowledge.tags IS
  'Controlled reusable content tags; domain-specific junction tables preserve referential integrity.';
CREATE INDEX tags_parent_idx ON knowledge.tags (parent_tag_id);

CREATE TABLE learning.formations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stable_key text NOT NULL UNIQUE,
  title text NOT NULL,
  description text,
  audience text,
  jurisdiction text NOT NULL DEFAULT 'FR',
  default_locale text NOT NULL DEFAULT 'fr-FR',
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  current_version_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE learning.formations IS
  'Top-level training programs such as DEA, Auxiliaire Ambulancier and IFSI.';

ALTER TABLE iam.user_roles
  ADD CONSTRAINT user_roles_formation_fk
  FOREIGN KEY (formation_id) REFERENCES learning.formations(id) ON DELETE CASCADE;

CREATE TABLE learning.formation_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  formation_id uuid NOT NULL REFERENCES learning.formations(id) ON DELETE CASCADE,
  version_number integer NOT NULL,
  title text NOT NULL,
  description text,
  effective_from timestamptz,
  published_at timestamptz,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  source_version_id uuid REFERENCES knowledge.source_versions(id) ON DELETE SET NULL,
  created_by uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (formation_id, version_number),
  CONSTRAINT formation_versions_number_ck CHECK (version_number > 0)
);
COMMENT ON TABLE learning.formation_versions IS
  'Immutable version envelope for a formation curriculum.';

ALTER TABLE learning.formations
  ADD CONSTRAINT formations_current_version_fk
  FOREIGN KEY (current_version_id) REFERENCES learning.formation_versions(id)
  ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE learning.blocks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  formation_version_id uuid NOT NULL REFERENCES learning.formation_versions(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  title text NOT NULL,
  subtitle text,
  description text,
  position integer NOT NULL,
  difficulty core.difficulty_level NOT NULL DEFAULT 'easy',
  estimated_minutes integer NOT NULL DEFAULT 0,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE (formation_version_id, stable_key),
  UNIQUE (formation_version_id, position),
  CONSTRAINT blocks_position_ck CHECK (position > 0),
  CONSTRAINT blocks_duration_ck CHECK (estimated_minutes >= 0),
  CONSTRAINT blocks_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE learning.blocks IS
  'Ordered curriculum domains grouping related learning paths.';
CREATE INDEX blocks_formation_status_idx
  ON learning.blocks (formation_version_id, status, position);

CREATE TABLE learning.paths (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  block_id uuid NOT NULL REFERENCES learning.blocks(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  title text NOT NULL,
  subtitle text,
  description text,
  objectives_text text,
  position integer NOT NULL,
  difficulty core.difficulty_level NOT NULL DEFAULT 'easy',
  estimated_minutes integer NOT NULL DEFAULT 0,
  xp_reward integer NOT NULL DEFAULT 0,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE (block_id, stable_key),
  UNIQUE (block_id, position),
  CONSTRAINT paths_position_ck CHECK (position > 0),
  CONSTRAINT paths_duration_ck CHECK (estimated_minutes >= 0),
  CONSTRAINT paths_xp_ck CHECK (xp_reward >= 0),
  CONSTRAINT paths_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE learning.paths IS
  'Ordered pedagogical paths within a block, independent of their lessons and rewards.';
CREATE INDEX paths_block_status_idx ON learning.paths (block_id, status, position);

CREATE TABLE learning.lessons (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  path_id uuid NOT NULL REFERENCES learning.paths(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  kind core.content_kind NOT NULL DEFAULT 'lesson',
  position integer NOT NULL,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  current_version_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (path_id, stable_key),
  UNIQUE (path_id, position),
  CONSTRAINT lessons_position_ck CHECK (position > 0)
);
COMMENT ON TABLE learning.lessons IS
  'Stable lesson identity; all editable pedagogical fields live in immutable lesson_versions.';
CREATE INDEX lessons_path_status_idx ON learning.lessons (path_id, status, position);

CREATE TABLE learning.lesson_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  lesson_id uuid NOT NULL REFERENCES learning.lessons(id) ON DELETE CASCADE,
  version_number integer NOT NULL,
  title text NOT NULL,
  subtitle text,
  summary text,
  pedagogical_content jsonb NOT NULL DEFAULT '{}'::jsonb,
  difficulty core.difficulty_level NOT NULL DEFAULT 'easy',
  estimated_minutes integer NOT NULL DEFAULT 0,
  passing_score numeric(5,2) NOT NULL DEFAULT 80,
  xp_reward integer NOT NULL DEFAULT 0,
  selection_config jsonb NOT NULL DEFAULT '{}'::jsonb,
  review_status core.review_status NOT NULL DEFAULT 'pending_review',
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  created_by uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (lesson_id, version_number),
  CONSTRAINT lesson_versions_number_ck CHECK (version_number > 0),
  CONSTRAINT lesson_versions_duration_ck CHECK (estimated_minutes >= 0),
  CONSTRAINT lesson_versions_passing_ck CHECK (passing_score BETWEEN 0 AND 100),
  CONSTRAINT lesson_versions_xp_ck CHECK (xp_reward >= 0),
  CONSTRAINT lesson_versions_content_ck CHECK (jsonb_typeof(pedagogical_content) = 'object'),
  CONSTRAINT lesson_versions_selection_ck CHECK (jsonb_typeof(selection_config) = 'object'),
  CONSTRAINT lesson_versions_published_ck CHECK (
    status <> 'published' OR published_at IS NOT NULL
  )
);
COMMENT ON TABLE learning.lesson_versions IS
  'Immutable lesson versions preserving official source specifications and renderer configuration.';
CREATE INDEX lesson_versions_lesson_status_idx
  ON learning.lesson_versions (lesson_id, status, version_number DESC);
CREATE INDEX lesson_versions_content_gin
  ON learning.lesson_versions USING gin (pedagogical_content jsonb_path_ops);

ALTER TABLE learning.lessons
  ADD CONSTRAINT lessons_current_version_fk
  FOREIGN KEY (current_version_id) REFERENCES learning.lesson_versions(id)
  ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE learning.chapters (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  lesson_version_id uuid NOT NULL REFERENCES learning.lesson_versions(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  title text NOT NULL,
  position integer NOT NULL,
  content jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE (lesson_version_id, stable_key),
  UNIQUE (lesson_version_id, position),
  CONSTRAINT chapters_position_ck CHECK (position > 0),
  CONSTRAINT chapters_content_ck CHECK (jsonb_typeof(content) = 'object')
);
COMMENT ON TABLE learning.chapters IS
  'Optional ordered internal lesson sections; not required for exercise-only lessons.';

CREATE TABLE learning.learning_objectives (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stable_key text NOT NULL UNIQUE,
  statement text NOT NULL,
  bloom_level text,
  measurable boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT learning_objectives_bloom_ck CHECK (
    bloom_level IS NULL OR bloom_level IN (
      'remember', 'understand', 'apply', 'analyze', 'evaluate', 'create'
    )
  )
);
COMMENT ON TABLE learning.learning_objectives IS
  'Reusable measurable pedagogical objectives independent from lesson wording and versions.';

CREATE TABLE learning.lesson_objectives (
  lesson_version_id uuid NOT NULL REFERENCES learning.lesson_versions(id) ON DELETE CASCADE,
  objective_id uuid NOT NULL REFERENCES learning.learning_objectives(id) ON DELETE RESTRICT,
  position integer NOT NULL DEFAULT 1,
  PRIMARY KEY (lesson_version_id, objective_id),
  CONSTRAINT lesson_objectives_position_ck CHECK (position > 0)
);
COMMENT ON TABLE learning.lesson_objectives IS
  'Ordered many-to-many mapping from a lesson version to its learning objectives.';

CREATE TABLE learning.lesson_competencies (
  lesson_version_id uuid NOT NULL REFERENCES learning.lesson_versions(id) ON DELETE CASCADE,
  competency_id uuid NOT NULL REFERENCES knowledge.competencies(id) ON DELETE RESTRICT,
  weight numeric(6,5) NOT NULL DEFAULT 1,
  PRIMARY KEY (lesson_version_id, competency_id),
  CONSTRAINT lesson_competencies_weight_ck CHECK (weight > 0 AND weight <= 1)
);
COMMENT ON TABLE learning.lesson_competencies IS
  'Weighted competency coverage of each immutable lesson version.';
CREATE INDEX lesson_competencies_competency_idx
  ON learning.lesson_competencies (competency_id, lesson_version_id);

CREATE TABLE learning.lesson_prerequisites (
  lesson_id uuid NOT NULL REFERENCES learning.lessons(id) ON DELETE CASCADE,
  prerequisite_lesson_id uuid NOT NULL REFERENCES learning.lessons(id) ON DELETE RESTRICT,
  minimum_score numeric(5,2) NOT NULL DEFAULT 80,
  required boolean NOT NULL DEFAULT true,
  PRIMARY KEY (lesson_id, prerequisite_lesson_id),
  CONSTRAINT lesson_prerequisites_not_self_ck CHECK (lesson_id <> prerequisite_lesson_id),
  CONSTRAINT lesson_prerequisites_score_ck CHECK (minimum_score BETWEEN 0 AND 100)
);
COMMENT ON TABLE learning.lesson_prerequisites IS
  'Explicit prerequisite graph used for server-authoritative unlocking.';
CREATE INDEX lesson_prerequisites_reverse_idx
  ON learning.lesson_prerequisites (prerequisite_lesson_id, lesson_id);

CREATE TABLE learning.lesson_assets (
  lesson_version_id uuid NOT NULL REFERENCES learning.lesson_versions(id) ON DELETE CASCADE,
  asset_id uuid NOT NULL REFERENCES media.assets(id) ON DELETE RESTRICT,
  usage text NOT NULL,
  position integer NOT NULL DEFAULT 1,
  configuration jsonb NOT NULL DEFAULT '{}'::jsonb,
  PRIMARY KEY (lesson_version_id, asset_id, usage),
  CONSTRAINT lesson_assets_position_ck CHECK (position > 0),
  CONSTRAINT lesson_assets_configuration_ck CHECK (jsonb_typeof(configuration) = 'object')
);
COMMENT ON TABLE learning.lesson_assets IS
  'Purpose-specific attachment of optimized media to lesson versions.';
CREATE INDEX lesson_assets_asset_idx ON learning.lesson_assets (asset_id);

CREATE TABLE learning.lesson_metadata (
  lesson_version_id uuid PRIMARY KEY REFERENCES learning.lesson_versions(id) ON DELETE CASCADE,
  prerequisites_text text[] NOT NULL DEFAULT ARRAY[]::text[],
  vocabulary text[] NOT NULL DEFAULT ARRAY[]::text[],
  audience_notes text,
  source_notes text,
  feature_requirements text[] NOT NULL DEFAULT ARRAY[]::text[],
  custom jsonb NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT lesson_metadata_custom_ck CHECK (jsonb_typeof(custom) = 'object')
);
COMMENT ON TABLE learning.lesson_metadata IS
  'Extensible lesson metadata separated from core version fields to keep curriculum rows stable.';

CREATE TABLE learning.path_prerequisites (
  path_id uuid NOT NULL REFERENCES learning.paths(id) ON DELETE CASCADE,
  prerequisite_path_id uuid NOT NULL REFERENCES learning.paths(id) ON DELETE RESTRICT,
  required boolean NOT NULL DEFAULT true,
  PRIMARY KEY (path_id, prerequisite_path_id),
  CONSTRAINT path_prerequisites_not_self_ck CHECK (path_id <> prerequisite_path_id)
);
COMMENT ON TABLE learning.path_prerequisites IS
  'Explicit path unlock graph, independent from visual ordering.';

CREATE TABLE learning.content_releases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  release_key text NOT NULL UNIQUE,
  formation_version_id uuid NOT NULL REFERENCES learning.formation_versions(id) ON DELETE RESTRICT,
  scope core.publication_scope NOT NULL DEFAULT 'formation',
  version_label text NOT NULL,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  manifest_checksum text,
  published_by uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT content_releases_published_ck CHECK (
    status <> 'published' OR published_at IS NOT NULL
  )
);
COMMENT ON TABLE learning.content_releases IS
  'Atomic curriculum release manifest enabling reproducible clients and safe cache invalidation.';

CREATE TABLE learning.content_release_items (
  release_id uuid NOT NULL REFERENCES learning.content_releases(id) ON DELETE CASCADE,
  lesson_version_id uuid NOT NULL REFERENCES learning.lesson_versions(id) ON DELETE RESTRICT,
  content_hash text NOT NULL,
  PRIMARY KEY (release_id, lesson_version_id)
);
COMMENT ON TABLE learning.content_release_items IS
  'Exact immutable lesson versions included in one release.';
CREATE INDEX content_release_items_lesson_idx
  ON learning.content_release_items (lesson_version_id, release_id);

CREATE TABLE learning.lesson_tags (
  lesson_version_id uuid NOT NULL REFERENCES learning.lesson_versions(id) ON DELETE CASCADE,
  tag_id uuid NOT NULL REFERENCES knowledge.tags(id) ON DELETE CASCADE,
  PRIMARY KEY (lesson_version_id, tag_id)
);
COMMENT ON TABLE learning.lesson_tags IS
  'Normalized tags for lesson discovery and analytics.';
CREATE INDEX lesson_tags_tag_idx ON learning.lesson_tags (tag_id, lesson_version_id);

CREATE TRIGGER assets_set_updated_at
BEFORE UPDATE ON media.assets
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();
CREATE TRIGGER source_documents_set_updated_at
BEFORE UPDATE ON knowledge.source_documents
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();
CREATE TRIGGER competencies_set_updated_at
BEFORE UPDATE ON knowledge.competencies
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();
CREATE TRIGGER medical_concepts_set_updated_at
BEFORE UPDATE ON knowledge.medical_concepts
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();
CREATE TRIGGER formations_set_updated_at
BEFORE UPDATE ON learning.formations
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();
CREATE TRIGGER lessons_set_updated_at
BEFORE UPDATE ON learning.lessons
FOR EACH ROW EXECUTE FUNCTION core.set_updated_at();

-- Pedagogical bank, extensible exercises, anatomy and clinical cases.

CREATE TABLE practice.question_banks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stable_key text NOT NULL UNIQUE,
  title text NOT NULL,
  description text,
  formation_id uuid REFERENCES learning.formations(id) ON DELETE CASCADE,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  selection_defaults jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT question_banks_selection_ck CHECK (jsonb_typeof(selection_defaults) = 'object')
);
COMMENT ON TABLE practice.question_banks IS
  'Reusable question pools shared by lessons, SRS, exams, Bosses, Pulse and Intervention.';
CREATE INDEX question_banks_formation_status_idx
  ON practice.question_banks (formation_id, status);

CREATE TABLE practice.lesson_question_banks (
  lesson_version_id uuid NOT NULL REFERENCES learning.lesson_versions(id) ON DELETE CASCADE,
  question_bank_id uuid NOT NULL REFERENCES practice.question_banks(id) ON DELETE RESTRICT,
  selection_weight numeric(6,5) NOT NULL DEFAULT 1,
  selection_config jsonb NOT NULL DEFAULT '{}'::jsonb,
  PRIMARY KEY (lesson_version_id, question_bank_id),
  CONSTRAINT lesson_question_banks_weight_ck CHECK (selection_weight > 0 AND selection_weight <= 1),
  CONSTRAINT lesson_question_banks_config_ck CHECK (jsonb_typeof(selection_config) = 'object')
);
COMMENT ON TABLE practice.lesson_question_banks IS
  'Data-driven mapping from lesson versions to one or more reusable question pools.';

CREATE TABLE practice.questions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_bank_id uuid NOT NULL REFERENCES practice.question_banks(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  type core.exercise_type NOT NULL,
  current_version_id uuid,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (question_bank_id, stable_key)
);
COMMENT ON TABLE practice.questions IS
  'Stable identity and exercise type for one pedagogical question; wording lives in versions.';
CREATE INDEX questions_bank_type_status_idx
  ON practice.questions (question_bank_id, type, status);

CREATE TABLE practice.question_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_id uuid NOT NULL REFERENCES practice.questions(id) ON DELETE CASCADE,
  version_number integer NOT NULL,
  prompt text NOT NULL,
  instructions text,
  difficulty core.difficulty_level NOT NULL DEFAULT 'easy',
  bloom_level text NOT NULL DEFAULT 'understand',
  estimated_seconds integer NOT NULL DEFAULT 30,
  scoring_config jsonb NOT NULL DEFAULT '{"maxScore":1}'::jsonb,
  renderer_config jsonb NOT NULL DEFAULT '{}'::jsonb,
  review_status core.review_status NOT NULL DEFAULT 'pending_review',
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  created_by uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (question_id, version_number),
  CONSTRAINT question_versions_number_ck CHECK (version_number > 0),
  CONSTRAINT question_versions_bloom_ck CHECK (
    bloom_level IN ('remember', 'understand', 'apply', 'analyze', 'evaluate', 'create')
  ),
  CONSTRAINT question_versions_duration_ck CHECK (estimated_seconds BETWEEN 1 AND 7200),
  CONSTRAINT question_versions_scoring_ck CHECK (jsonb_typeof(scoring_config) = 'object'),
  CONSTRAINT question_versions_renderer_ck CHECK (jsonb_typeof(renderer_config) = 'object'),
  CONSTRAINT question_versions_published_ck CHECK (
    status <> 'published' OR published_at IS NOT NULL
  )
);
COMMENT ON TABLE practice.question_versions IS
  'Immutable wording, level and renderer configuration for a question version.';
CREATE INDEX question_versions_question_status_idx
  ON practice.question_versions (question_id, status, version_number DESC);
CREATE INDEX question_versions_renderer_gin
  ON practice.question_versions USING gin (renderer_config jsonb_path_ops);

ALTER TABLE practice.questions
  ADD CONSTRAINT questions_current_version_fk
  FOREIGN KEY (current_version_id) REFERENCES practice.question_versions(id)
  ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE practice.choices (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  label text NOT NULL,
  position integer NOT NULL,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE (question_version_id, stable_key),
  UNIQUE (question_version_id, position),
  CONSTRAINT choices_position_ck CHECK (position > 0),
  CONSTRAINT choices_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE practice.choices IS
  'Answer choices with stable IDs; visual position is never the source of truth.';
CREATE INDEX choices_question_idx
  ON practice.choices (question_version_id, position);

CREATE TABLE practice.answer_keys (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  choice_id uuid REFERENCES practice.choices(id) ON DELETE CASCADE,
  accepted_payload jsonb,
  weight numeric(7,5) NOT NULL DEFAULT 1,
  required boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT answer_keys_target_ck CHECK (
    (choice_id IS NOT NULL AND accepted_payload IS NULL)
    OR (choice_id IS NULL AND accepted_payload IS NOT NULL)
  ),
  CONSTRAINT answer_keys_weight_ck CHECK (weight >= 0 AND weight <= 1),
  CONSTRAINT answer_keys_payload_ck CHECK (
    accepted_payload IS NULL OR jsonb_typeof(accepted_payload) IN ('object', 'array', 'string', 'number', 'boolean')
  )
);
COMMENT ON TABLE practice.answer_keys IS
  'Canonical corrections by stable choice ID or structured accepted payload; supports single and multiple answers.';
CREATE UNIQUE INDEX answer_keys_choice_uidx
  ON practice.answer_keys (question_version_id, choice_id)
  WHERE choice_id IS NOT NULL;
CREATE INDEX answer_keys_question_idx
  ON practice.answer_keys (question_version_id);

CREATE TABLE practice.explanations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  choice_id uuid REFERENCES practice.choices(id) ON DELETE CASCADE,
  explanation_kind text NOT NULL DEFAULT 'general',
  content text NOT NULL,
  priority_note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT explanations_kind_ck CHECK (
    explanation_kind IN ('general', 'correct', 'distractor', 'clinical', 'regulatory')
  )
);
COMMENT ON TABLE practice.explanations IS
  'General and choice-specific pedagogical feedback, including clinical or regulatory priority.';
CREATE UNIQUE INDEX explanations_scope_uidx
  ON practice.explanations (
    question_version_id,
    COALESCE(choice_id, '00000000-0000-0000-0000-000000000000'::uuid),
    explanation_kind
  );

CREATE TABLE practice.hints (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  position integer NOT NULL,
  content text NOT NULL,
  xp_penalty integer NOT NULL DEFAULT 0,
  unlock_after_seconds integer,
  UNIQUE (question_version_id, position),
  CONSTRAINT hints_position_ck CHECK (position > 0),
  CONSTRAINT hints_penalty_ck CHECK (xp_penalty >= 0),
  CONSTRAINT hints_unlock_ck CHECK (unlock_after_seconds IS NULL OR unlock_after_seconds >= 0)
);
COMMENT ON TABLE practice.hints IS
  'Ordered progressive hints with optional timing and XP cost.';

CREATE TABLE practice.question_competencies (
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  competency_id uuid NOT NULL REFERENCES knowledge.competencies(id) ON DELETE RESTRICT,
  weight numeric(6,5) NOT NULL DEFAULT 1,
  PRIMARY KEY (question_version_id, competency_id),
  CONSTRAINT question_competencies_weight_ck CHECK (weight > 0 AND weight <= 1)
);
COMMENT ON TABLE practice.question_competencies IS
  'Weighted competencies measured by an immutable question version.';
CREATE INDEX question_competencies_competency_idx
  ON practice.question_competencies (competency_id, question_version_id);

CREATE TABLE practice.question_sources (
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  source_section_id uuid NOT NULL REFERENCES knowledge.source_sections(id) ON DELETE RESTRICT,
  evidence_note text,
  PRIMARY KEY (question_version_id, source_section_id)
);
COMMENT ON TABLE practice.question_sources IS
  'Mandatory page- or article-level evidence for every source-backed question.';
CREATE INDEX question_sources_section_idx
  ON practice.question_sources (source_section_id, question_version_id);

CREATE TABLE practice.question_tags (
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  tag_id uuid NOT NULL REFERENCES knowledge.tags(id) ON DELETE CASCADE,
  PRIMARY KEY (question_version_id, tag_id)
);
COMMENT ON TABLE practice.question_tags IS
  'Normalized tags for search, adaptive selection and reuse across learning modes.';
CREATE INDEX question_tags_tag_idx
  ON practice.question_tags (tag_id, question_version_id);

CREATE TABLE practice.question_assets (
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  asset_id uuid NOT NULL REFERENCES media.assets(id) ON DELETE RESTRICT,
  usage text NOT NULL,
  position integer NOT NULL DEFAULT 1,
  configuration jsonb NOT NULL DEFAULT '{}'::jsonb,
  PRIMARY KEY (question_version_id, asset_id, usage),
  CONSTRAINT question_assets_position_ck CHECK (position > 0),
  CONSTRAINT question_assets_config_ck CHECK (jsonb_typeof(configuration) = 'object')
);
COMMENT ON TABLE practice.question_assets IS
  'Images, audio, video, Lottie or 3D media used by a question version.';

CREATE TABLE practice.matching_pairs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  left_content text NOT NULL,
  right_content text NOT NULL,
  position integer NOT NULL,
  UNIQUE (question_version_id, stable_key),
  UNIQUE (question_version_id, position),
  CONSTRAINT matching_pairs_position_ck CHECK (position > 0)
);
COMMENT ON TABLE practice.matching_pairs IS
  'Normalized correct pairs for matching exercises; clients randomize both sides independently.';

CREATE TABLE practice.ordering_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  content text NOT NULL,
  correct_position integer NOT NULL,
  UNIQUE (question_version_id, stable_key),
  UNIQUE (question_version_id, correct_position),
  CONSTRAINT ordering_items_position_ck CHECK (correct_position > 0)
);
COMMENT ON TABLE practice.ordering_items IS
  'Stable items and canonical sequence for chronological and procedural ordering.';

CREATE TABLE practice.fill_blank_slots (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  position integer NOT NULL,
  accepted_answers text[] NOT NULL,
  case_sensitive boolean NOT NULL DEFAULT false,
  accent_sensitive boolean NOT NULL DEFAULT false,
  UNIQUE (question_version_id, stable_key),
  UNIQUE (question_version_id, position),
  CONSTRAINT fill_blank_slots_position_ck CHECK (position > 0),
  CONSTRAINT fill_blank_slots_answers_ck CHECK (cardinality(accepted_answers) > 0)
);
COMMENT ON TABLE practice.fill_blank_slots IS
  'Normalized blank positions and accepted textual forms for fill-in exercises.';

CREATE TABLE practice.calculation_rules (
  question_version_id uuid PRIMARY KEY REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  expected_value numeric NOT NULL,
  tolerance numeric NOT NULL DEFAULT 0,
  unit text,
  rounding_scale integer,
  formula_reference text,
  CONSTRAINT calculation_rules_tolerance_ck CHECK (tolerance >= 0),
  CONSTRAINT calculation_rules_rounding_ck CHECK (
    rounding_scale IS NULL OR rounding_scale BETWEEN 0 AND 10
  )
);
COMMENT ON TABLE practice.calculation_rules IS
  'Server-side numeric correction rule for dosage, timing or other approved calculations.';

CREATE TABLE practice.exercise_definitions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stable_key text NOT NULL UNIQUE,
  title text NOT NULL,
  kind core.content_kind NOT NULL DEFAULT 'lesson',
  current_version_id uuid,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE practice.exercise_definitions IS
  'Stable aggregate for a composed activity such as a lesson session, quiz, Boss or exam.';

CREATE TABLE practice.exercise_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  exercise_id uuid NOT NULL REFERENCES practice.exercise_definitions(id) ON DELETE CASCADE,
  version_number integer NOT NULL,
  instructions text,
  selection_config jsonb NOT NULL DEFAULT '{}'::jsonb,
  scoring_config jsonb NOT NULL DEFAULT '{}'::jsonb,
  time_limit_seconds integer,
  attempt_limit integer,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  created_by uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (exercise_id, version_number),
  CONSTRAINT exercise_versions_number_ck CHECK (version_number > 0),
  CONSTRAINT exercise_versions_selection_ck CHECK (jsonb_typeof(selection_config) = 'object'),
  CONSTRAINT exercise_versions_scoring_ck CHECK (jsonb_typeof(scoring_config) = 'object'),
  CONSTRAINT exercise_versions_time_ck CHECK (time_limit_seconds IS NULL OR time_limit_seconds > 0),
  CONSTRAINT exercise_versions_attempt_limit_ck CHECK (attempt_limit IS NULL OR attempt_limit > 0),
  CONSTRAINT exercise_versions_published_ck CHECK (
    status <> 'published' OR published_at IS NOT NULL
  )
);
COMMENT ON TABLE practice.exercise_versions IS
  'Immutable composed-activity rules supporting deterministic retries and historical scoring.';

ALTER TABLE practice.exercise_definitions
  ADD CONSTRAINT exercise_definitions_current_version_fk
  FOREIGN KEY (current_version_id) REFERENCES practice.exercise_versions(id)
  ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE practice.exercise_questions (
  exercise_version_id uuid NOT NULL REFERENCES practice.exercise_versions(id) ON DELETE CASCADE,
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE RESTRICT,
  position integer,
  weight numeric(7,5) NOT NULL DEFAULT 1,
  required boolean NOT NULL DEFAULT false,
  PRIMARY KEY (exercise_version_id, question_version_id),
  CONSTRAINT exercise_questions_position_ck CHECK (position IS NULL OR position > 0),
  CONSTRAINT exercise_questions_weight_ck CHECK (weight > 0)
);
COMMENT ON TABLE practice.exercise_questions IS
  'Optional fixed membership of an activity; selection_config can instead sample question banks.';
CREATE INDEX exercise_questions_question_idx
  ON practice.exercise_questions (question_version_id, exercise_version_id);

CREATE TABLE practice.lesson_exercises (
  lesson_version_id uuid NOT NULL REFERENCES learning.lesson_versions(id) ON DELETE CASCADE,
  exercise_version_id uuid NOT NULL REFERENCES practice.exercise_versions(id) ON DELETE RESTRICT,
  position integer NOT NULL,
  PRIMARY KEY (lesson_version_id, exercise_version_id),
  UNIQUE (lesson_version_id, position),
  CONSTRAINT lesson_exercises_position_ck CHECK (position > 0)
);
COMMENT ON TABLE practice.lesson_exercises IS
  'Ordered activities attached to a lesson version; no pedagogical text is hard-coded in React.';

CREATE TABLE anatomy.body_systems (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  concept_id uuid NOT NULL UNIQUE REFERENCES knowledge.medical_concepts(id) ON DELETE RESTRICT,
  stable_key text NOT NULL UNIQUE,
  name text NOT NULL,
  description text,
  sort_order integer NOT NULL DEFAULT 0,
  review_status core.review_status NOT NULL DEFAULT 'pending_review',
  status core.lifecycle_status NOT NULL DEFAULT 'draft'
);
COMMENT ON TABLE anatomy.body_systems IS
  'Canonical anatomical systems linked to the shared medical concept graph.';

CREATE TABLE anatomy.structures (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  concept_id uuid NOT NULL UNIQUE REFERENCES knowledge.medical_concepts(id) ON DELETE RESTRICT,
  body_system_id uuid REFERENCES anatomy.body_systems(id) ON DELETE SET NULL,
  parent_structure_id uuid REFERENCES anatomy.structures(id) ON DELETE RESTRICT,
  stable_key text NOT NULL UNIQUE,
  structure_type text NOT NULL,
  name text NOT NULL,
  laterality text,
  description text,
  review_status core.review_status NOT NULL DEFAULT 'pending_review',
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT anatomy_structure_type_ck CHECK (
    structure_type IN ('region', 'bone', 'muscle', 'organ', 'nerve', 'vessel', 'tissue', 'landmark', 'other')
  ),
  CONSTRAINT anatomy_laterality_ck CHECK (
    laterality IS NULL OR laterality IN ('left', 'right', 'bilateral', 'midline', 'not_applicable')
  ),
  CONSTRAINT anatomy_structures_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE anatomy.structures IS
  'Unified 3NF anatomy entity for bones, muscles, organs, nerves, vessels, regions and landmarks.';
CREATE INDEX anatomy_structures_system_type_idx
  ON anatomy.structures (body_system_id, structure_type, status);
CREATE INDEX anatomy_structures_parent_idx ON anatomy.structures (parent_structure_id);

CREATE TABLE anatomy.structure_relationships (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_structure_id uuid NOT NULL REFERENCES anatomy.structures(id) ON DELETE CASCADE,
  target_structure_id uuid NOT NULL REFERENCES anatomy.structures(id) ON DELETE CASCADE,
  relationship core.relationship_kind NOT NULL,
  source_section_id uuid REFERENCES knowledge.source_sections(id) ON DELETE SET NULL,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE (source_structure_id, target_structure_id, relationship),
  CONSTRAINT anatomy_relationship_not_self_ck CHECK (source_structure_id <> target_structure_id),
  CONSTRAINT anatomy_relationship_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE anatomy.structure_relationships IS
  'Sourced anatomical hierarchy and spatial/functional relationships.';
CREATE INDEX structure_relationships_target_idx
  ON anatomy.structure_relationships (target_structure_id, relationship);

CREATE TABLE anatomy.models (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stable_key text NOT NULL UNIQUE,
  title text NOT NULL,
  model_asset_id uuid NOT NULL REFERENCES media.assets(id) ON DELETE RESTRICT,
  preview_asset_id uuid REFERENCES media.assets(id) ON DELETE SET NULL,
  coordinate_system text NOT NULL DEFAULT 'right_handed_y_up',
  units text NOT NULL DEFAULT 'meters',
  version_label text NOT NULL,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT anatomy_models_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE anatomy.models IS
  'Versioned optimized 3D anatomy model catalog stored through media assets.';

CREATE TABLE anatomy.model_nodes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  model_id uuid NOT NULL REFERENCES anatomy.models(id) ON DELETE CASCADE,
  structure_id uuid REFERENCES anatomy.structures(id) ON DELETE SET NULL,
  parent_node_id uuid REFERENCES anatomy.model_nodes(id) ON DELETE CASCADE,
  node_key text NOT NULL,
  label text,
  transform jsonb NOT NULL DEFAULT '{}'::jsonb,
  interaction_config jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE (model_id, node_key),
  CONSTRAINT anatomy_model_nodes_transform_ck CHECK (jsonb_typeof(transform) = 'object'),
  CONSTRAINT anatomy_model_nodes_interaction_ck CHECK (jsonb_typeof(interaction_config) = 'object')
);
COMMENT ON TABLE anatomy.model_nodes IS
  'Addressable model scene nodes mapped to canonical anatomy structures.';
CREATE INDEX anatomy_model_nodes_structure_idx
  ON anatomy.model_nodes (structure_id) WHERE structure_id IS NOT NULL;

CREATE TABLE anatomy.hotspots (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  model_id uuid NOT NULL REFERENCES anatomy.models(id) ON DELETE CASCADE,
  structure_id uuid NOT NULL REFERENCES anatomy.structures(id) ON DELETE RESTRICT,
  stable_key text NOT NULL,
  position jsonb NOT NULL,
  camera_target jsonb,
  radius numeric NOT NULL DEFAULT 0.02,
  label text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE (model_id, stable_key),
  CONSTRAINT anatomy_hotspots_radius_ck CHECK (radius > 0),
  CONSTRAINT anatomy_hotspots_position_ck CHECK (jsonb_typeof(position) = 'object'),
  CONSTRAINT anatomy_hotspots_camera_ck CHECK (
    camera_target IS NULL OR jsonb_typeof(camera_target) = 'object'
  ),
  CONSTRAINT anatomy_hotspots_metadata_ck CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE anatomy.hotspots IS
  'Interactive coordinates and camera targets for anatomical localization exercises.';
CREATE INDEX anatomy_hotspots_structure_idx
  ON anatomy.hotspots (structure_id, model_id);

CREATE TABLE practice.hotspot_targets (
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE CASCADE,
  hotspot_id uuid NOT NULL REFERENCES anatomy.hotspots(id) ON DELETE RESTRICT,
  weight numeric(7,5) NOT NULL DEFAULT 1,
  required boolean NOT NULL DEFAULT true,
  PRIMARY KEY (question_version_id, hotspot_id),
  CONSTRAINT hotspot_targets_weight_ck CHECK (weight > 0 AND weight <= 1)
);
COMMENT ON TABLE practice.hotspot_targets IS
  'Canonical accepted anatomy hotspots for image or 3D localization questions.';

CREATE TABLE clinical.cases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stable_key text NOT NULL UNIQUE,
  title text NOT NULL,
  domain_id uuid NOT NULL REFERENCES knowledge.medical_domains(id) ON DELETE RESTRICT,
  difficulty core.difficulty_level NOT NULL,
  current_version_id uuid,
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE clinical.cases IS
  'Stable identity of a clinical scenario reusable in lessons, Bosses and Intervention.';

CREATE TABLE clinical.case_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  case_id uuid NOT NULL REFERENCES clinical.cases(id) ON DELETE CASCADE,
  version_number integer NOT NULL,
  summary text NOT NULL,
  patient_profile jsonb NOT NULL,
  initial_state jsonb NOT NULL,
  scoring_config jsonb NOT NULL DEFAULT '{}'::jsonb,
  timing_config jsonb NOT NULL DEFAULT '{}'::jsonb,
  review_status core.review_status NOT NULL DEFAULT 'pending_review',
  status core.lifecycle_status NOT NULL DEFAULT 'draft',
  created_by uuid REFERENCES iam.user_accounts(user_id) ON DELETE SET NULL,
  published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (case_id, version_number),
  CONSTRAINT case_versions_number_ck CHECK (version_number > 0),
  CONSTRAINT case_versions_patient_ck CHECK (jsonb_typeof(patient_profile) = 'object'),
  CONSTRAINT case_versions_state_ck CHECK (jsonb_typeof(initial_state) = 'object'),
  CONSTRAINT case_versions_scoring_ck CHECK (jsonb_typeof(scoring_config) = 'object'),
  CONSTRAINT case_versions_timing_ck CHECK (jsonb_typeof(timing_config) = 'object'),
  CONSTRAINT case_versions_published_ck CHECK (
    status <> 'published' OR published_at IS NOT NULL
  )
);
COMMENT ON TABLE clinical.case_versions IS
  'Immutable, medically reviewed scenario version with initial state, score and timing rules.';

ALTER TABLE clinical.cases
  ADD CONSTRAINT clinical_cases_current_version_fk
  FOREIGN KEY (current_version_id) REFERENCES clinical.case_versions(id)
  ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE clinical.case_steps (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  case_version_id uuid NOT NULL REFERENCES clinical.case_versions(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  phase text NOT NULL,
  position integer NOT NULL,
  prompt text NOT NULL,
  state_patch jsonb NOT NULL DEFAULT '{}'::jsonb,
  time_cost_seconds integer NOT NULL DEFAULT 0,
  UNIQUE (case_version_id, stable_key),
  UNIQUE (case_version_id, position),
  CONSTRAINT case_steps_position_ck CHECK (position > 0),
  CONSTRAINT case_steps_time_ck CHECK (time_cost_seconds >= 0),
  CONSTRAINT case_steps_state_ck CHECK (jsonb_typeof(state_patch) = 'object')
);
COMMENT ON TABLE clinical.case_steps IS
  'Ordered reusable stages of a case, such as alert, safety, ABCDE, decisions, transport and debrief.';

CREATE TABLE clinical.case_step_questions (
  case_step_id uuid NOT NULL REFERENCES clinical.case_steps(id) ON DELETE CASCADE,
  question_version_id uuid NOT NULL REFERENCES practice.question_versions(id) ON DELETE RESTRICT,
  position integer NOT NULL,
  PRIMARY KEY (case_step_id, question_version_id),
  UNIQUE (case_step_id, position),
  CONSTRAINT case_step_questions_position_ck CHECK (position > 0)
);
COMMENT ON TABLE clinical.case_step_questions IS
  'Links case steps to ordinary versioned questions, avoiding a second question engine.';

CREATE TABLE clinical.case_decisions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  case_step_id uuid NOT NULL REFERENCES clinical.case_steps(id) ON DELETE CASCADE,
  stable_key text NOT NULL,
  label text NOT NULL,
  next_step_id uuid REFERENCES clinical.case_steps(id) ON DELETE SET NULL,
  score_delta numeric NOT NULL DEFAULT 0,
  xp_delta integer NOT NULL DEFAULT 0,
  time_delta_seconds integer NOT NULL DEFAULT 0,
  patient_state_patch jsonb NOT NULL DEFAULT '{}'::jsonb,
  feedback text NOT NULL,
  UNIQUE (case_step_id, stable_key),
  CONSTRAINT case_decisions_patient_state_ck CHECK (jsonb_typeof(patient_state_patch) = 'object')
);
COMMENT ON TABLE clinical.case_decisions IS
  'Branching, scored decisions with explicit patient-state and timing consequences.';
CREATE INDEX case_decisions_next_step_idx
  ON clinical.case_decisions (next_step_id) WHERE next_step_id IS NOT NULL;

CREATE TABLE clinical.case_sources (
  case_version_id uuid NOT NULL REFERENCES clinical.case_versions(id) ON DELETE CASCADE,
  source_section_id uuid NOT NULL REFERENCES knowledge.source_sections(id) ON DELETE RESTRICT,
  evidence_note text,
  PRIMARY KEY (case_version_id, source_section_id)
);
COMMENT ON TABLE clinical.case_sources IS
  'Precise evidence sources for the clinical scenario and its decision logic.';

